                    // Keep an empty string when no reference is provided; payments.reference is NOT NULL.
                    try{$retry=$pdo->prepare("SELECT paymentID FROM payments WHERE userID=? AND eventID=? AND status='Rejected' ORDER BY submittedAt DESC LIMIT 1");$retry->execute([$uid,$eventId]);$rejectedID=(int)$retry->fetchColumn();if($rejectedID){$q=$pdo->prepare("UPDATE payments SET amount=?,method=?,reference=?,proofPath=?,status='Pending',submittedAt=NOW() WHERE paymentID=? AND userID=? AND status='Rejected'");$q->execute([$amount,$method,$reference,$proofPath,$rejectedID,$uid]);}else{$q=$pdo->prepare("INSERT INTO payments (userID,eventID,amount,method,reference,proofPath,status,submittedAt) VALUES (?,?,?,?,?,?,'Pending',NOW())");$q->execute([$uid,$eventId,$amount,$method,$reference,$proofPath]);}sems_notify($pdo,(int)$payEvent['createdBy'],'Student payment submitted',$user['name'].' submitted a payment for '.$payEvent['eventName'].'.','teacher_payments.php');$message=$method==='Cash'?'Cash payment recorded and sent for review.':$method.' receipt submitted for review.';}catch(Throwable $saveError){if($proofPath)@unlink($uploadDir.'/'.$proofPath);throw $saveError;}
