        foreach($calendarRows as $item){$poster=$item['eventPoster']?:'assets/sems-school-activities.jpg';echo '<article class="calendar-result-card"><a class="calendar-result-image" href="event_detail.php?eventID='.(int)$item['eventID'].'"><img src="'.school_h($poster).'" alt="'.school_h($item['itemName']).'"><span class="calendar-result-type">'.school_h($item['itemStatus']).'</span></a><div class="calendar-result-body"><h3><a href="event_detail.php?eventID='.(int)$item['eventID'].'">'.school_h($item['itemName']).'</a></h3><p>'.school_h(date('D, d M Y',strtotime($item['itemDate']))).' · '.school_h(date('h:i A',strtotime($item['eventTime']))).'–'.school_h(date('h:i A',strtotime($item['eventEndTime']?:$item['eventTime']))).' · '.school_h($item['itemPlace']).'</p><p>'.(int)$item['registered'].' / '.(int)$item['capacity'].' registered · RM '.number_format((float)$item['fee'],2).'</p><p class="calendar-result-handler">Handled by '.school_h($item['itemHandler']).'</p><a class="calendar-result-link" href="event_detail.php?eventID='.(int)$item['eventID'].'">View event and feedback</a></div></article>';}
        if(!$calendarRows)echo '<p class="calendar-empty">No events this month.</p>';
        echo '</div>';
    }else{$rows=[];foreach($calendarRows as $v)$rows[]=[school_h(date('D, d M Y',strtotime($v['itemDate']))),school_h($v['itemName']),school_h($v['itemType']),school_h($v['itemPlace']),school_h($v['itemHandler']),school_h($v['itemStatus'])];portal_table(['Date','Event / task','Type','Location','Handled by','Status'],$rows);}echo '</section>';
} elseif ($page==='inbox') {
    $markViewed=$pdo->prepare('UPDATE notifications SET isRead=1 WHERE userID=? AND isRead=0');$markViewed->execute([$uid]);
    $q=$pdo->prepare('SELECT notificationID,title,message,link,isRead,createdAt FROM notifications WHERE userID=? ORDER BY createdAt DESC LIMIT 100');$q->execute([$uid]);$notices=$q->fetchAll();
    echo '<section class="portal-card"><h2>Notifications</h2><p>Updates about your events, registrations, assigned tasks and attendance.</p>';
    if(!$notices)echo '<p>Your inbox is clear.</p>';
    foreach($notices as $notice){echo '<article class="portal-notice '.((int)$notice['isRead']?'':'success').'" style="margin:12px 0"><strong>'.school_h($notice['title']).'</strong><p>'.school_h($notice['message']).'</p><small>'.school_h($notice['createdAt']).'</small>';if($notice['link'])echo ' Â· <a href="'.school_h($notice['link']).'">Open</a>';if(!(int)$notice['isRead'])echo '<form method="post" class="inline-form"><input type="hidden" name="csrf" value="'.school_h($csrf).'"><button class="small-button" name="mark_read" value="'.(int)$notice['notificationID'].'">Mark as read</button></form>';echo '</article>';}
    echo '</section>';
} elseif ($page==='profile') {
    if (in_array($role,['Admin','Principal'],true)) { $activePrincipal=$pdo->query("SELECT name,email FROM users WHERE role='Principal' AND status='Active' LIMIT 1")->fetch(PDO::FETCH_ASSOC); echo '<section class="portal-card"><h2>Change Principal</h2><p>Current Principal: '.school_h($activePrincipal['name']??'Not set').'. The previous account will be deactivated and its appointment history kept.</p><form method="post" class="portal-form"><input type="hidden" name="csrf" value="'.school_h($csrf).'"><label>New Principal name<input name="principal_name" maxlength="100" required></label><label>New Principal email<input type="email" name="principal_email" maxlength="100" required></label><label>Temporary password (at least 8 characters)<input type="password" name="principal_password" minlength="8" required></label><button class="small-button" name="change_principal" value="1">Change Principal</button></form></section>'; }
    echo '<section class="portal-card"><h2>Account details</h2><form method="post" class="portal-form"><input type="hidden" name="csrf" value="'.school_h($csrf).'"><label>Full name<input name="name" required maxlength="100" value="'.school_h($user['name']).'"></label><label>Email<input type="email" name="email" required maxlength="100" value="'.school_h($user['email']).'"></label><label>Student ID<input disabled value="'.school_h($studentId).'"></label><button class="small-button">Save profile</button></form></section>';
}
