ument.getElementById("oversight-prev"),next=document.getElementById("oversight-next"),page=0,size=4;function render(){size=Math.max(1,getComputedStyle(grid).gridTemplateColumns.split(" ").length);var term=(search.value||"").trim().toLowerCase(),matches=cards.filter(function(card){return card.textContent.toLowerCase().includes(term);}),pages=Math.max(1,Math.ceil(matches.length/size));page=Math.min(page,pages-1);cards.forEach(function(card){card.hidden=true;});matches.slice(page*size,(page+1)*size).forEach(function(card){card.hidden=false;});label.textContent=matches.length?"Showing "+(page*size+1)+"–"+Math.min((page+1)*size,matches.length)+" of "+matches.length:"No events found";prev.disabled=page===0;next.disabled=page>=pages-1;}search.addEventListener("input",function(){page=0;render();});prev.addEventListener("click",function(){page--;render();});next.addEventListener("click",function(){page++;render();});window.addEventListener("resize",render);render();}});</script></body></html>




































